const items = $input.all();

if (!items.length || !items[0].json.StudentName) {
  return [{ json: { 
    hasLowAttendance: false,
    message: 'No attendance records found.'
  }}];
}

// Group records by student
const students = {};
items.forEach(item => {
  const name = item.json.StudentName;
  if (!name) return;
  if (!students[name]) {
    students[name] = { total: 0, present: 0, absent: 0, late: 0 };
  }
  students[name].total++;
  const status = (item.json.Status || '').toLowerCase();
  if (status === 'present') students[name].present++;
  else if (status === 'absent') students[name].absent++;
  else if (status === 'late')   students[name].late++;
});

// Calculate percentages
const results = [];
Object.entries(students).forEach(([name, data]) => {
  const effectivePresent = data.present + (data.late * 0.5);
  const percentage = data.total > 0 
    ? Math.round((effectivePresent / data.total) * 100) 
    : 100;

  results.push({
    studentName:  name,
    total:        data.total,
    present:      data.present,
    absent:       data.absent,
    late:         data.late,
    percentage:   percentage,
    isBelowLimit: percentage < 75,
    status:       percentage < 60  ? 'Critical' :
                  percentage < 75  ? 'Warning'  : 'Good'
  });
});

// Only return students below 75%
const lowAttendance = results.filter(s => s.isBelowLimit);

if (!lowAttendance.length) {
  return [{ json: { 
    hasLowAttendance: false,
    message: 'All students above 75% attendance. No alerts needed.'
  }}];
}

return lowAttendance.map(s => ({
  json: { ...s, hasLowAttendance: true }
}));

const items = $input.all();

const critical = items.filter(i => i.json.status === 'Critical');
const warning  = items.filter(i => i.json.status === 'Warning');

let message = 'Attendance Alert — ' + new Date().toLocaleDateString('en-GB') + '\n\n';

if (critical.length) {
  message += 'CRITICAL (below 60%):\n';
  critical.forEach(i => {
    message += `• ${i.json.studentName}: ${i.json.percentage}% `;
    message += `(${i.json.present} present, ${i.json.absent} absent, ${i.json.late} late out of ${i.json.total} days)\n`;
  });
  message += '\n';
}

if (warning.length) {
  message += 'WARNING (60-75%):\n';
  warning.forEach(i => {
    message += `• ${i.json.studentName}: ${i.json.percentage}% `;
    message += `(${i.json.present} present, ${i.json.absent} absent, ${i.json.late} late out of ${i.json.total} days)\n`;
  });
}

message += '\nPlease follow up with the relevant parents.';

return [{ json: { alertMessage: message, count: items.length } }];
